1	// Switchboard's web page: pair a browser from the pairing window's QR,
2	// list the sessions with the waiting ones first, read one, and reply.
3	// It speaks the remote port's /api/v1 as a native client does, with
4	// two differences: the token is a cookie this script never sees, and
5	// changes arrive by polling, the events socket only hastening them.
6	// Text from the host is set with textContent only, never as markup.
7	'use strict';
8	
9	// Every route the page calls, method and path. A host test reads this
10	// table and checks that each one is served.
11	const API = {
12	  info: 'GET /api/v1/info',
13	  pair: 'POST /api/v1/pair',
14	  me: 'GET /api/v1/me',
15	  projects: 'GET /api/v1/projects',
16	  sessions: 'GET /api/v1/projects/{id}/sessions',
17	  waiting: 'GET /api/v1/waiting',
18	  lastResponse: 'GET /api/v1/sessions/{id}/last-response',
19	  screen: 'GET /api/v1/sessions/{id}/screen',
20	  send: 'POST /api/v1/sessions/{id}/send',
21	  events: 'GET /api/v1/events',
22	};
23	
24	const STORE_KEY = 'switchboard-host';
25	const POLL_FAST_MS = 3000;
26	const POLL_SLOW_MS = 20000;
27	const SOCKET_RETRY_MS = 5000;
28	const SOCKET_RETRY_MAX_MS = 60000;
29	
30	// --- pure parts, tested with node --test
31	
32	/** The invite in a URL fragment, `#code=…&key=…&id=…`, or null. */
33	function parseFragment(hash) {
34	  const text = (hash || '').replace(/^#/, '');
35	  const fields = {};
36	  for (const pair of text.split('&')) {
37	    const at = pair.indexOf('=');
38	    if (at <= 0) continue;
39	    try {
40	      fields[pair.slice(0, at)] = decodeURIComponent(pair.slice(at + 1));
41	    } catch (_) {
42	      return null;
43	    }
44	  }
45	  if (!fields.code || !fields.key || !fields.id) return null;
46	  return { code: fields.code, key: fields.key.toLowerCase(), id: fields.id.toLowerCase() };
47	}
48	
49	/** "Safari on iPhone", from the user agent; the host shows it. */
50	function deviceName(ua, touchPoints) {
51	  ua = ua || '';
52	  let browser = 'Safari';
53	  if (/Edg\//.test(ua)) browser = 'Edge';
54	  else if (/Chrome\/|CriOS\//.test(ua)) browser = 'Chrome';
55	  else if (/Firefox\/|FxiOS\//.test(ua)) browser = 'Firefox';
56	  else if (!/Safari\//.test(ua)) return 'Browser';
57	  let device = null;
58	  if (/iPhone/.test(ua)) device = 'iPhone';
59	  else if (/iPad/.test(ua) || (/Macintosh/.test(ua) && touchPoints > 1)) device = 'iPad';
60	  else if (/Android/.test(ua)) device = 'Android';
61	  else if (/Macintosh|Mac OS X/.test(ua)) device = 'Mac';
62	  else if (/Windows/.test(ua)) device = 'Windows';
63	  else if (/Linux/.test(ua)) device = 'Linux';
64	  return device ? `${browser} on ${device}` : 'Browser';
65	}
66	
67	/**
68	 * What a 401 means, told from `/info`, which answers anyone: the host
69	 * this page paired with, under the same key, no longer knows the device
70	 * ("removed"); a different key or id ("changed"); no answer
71	 * ("unreachable"); or nothing was ever paired here ("unpaired").
72	 */
73	function inferUnauthorized(stored, info) {
74	  if (!stored) return 'unpaired';
75	  if (!info) return 'unreachable';
76	  const same = String(info.server_id).toLowerCase() === stored.server_id
77	    && String(info.spki_sha256).toLowerCase() === stored.spki_sha256;
78	  return same ? 'removed' : 'changed';
79	}
80	
81	/**
82	 * Whether a reply at `next` may replace what is held at `held`: a
83	 * restarted host (a new epoch) always may; otherwise only a revision at
84	 * or past the held one, so a late reply never undoes a newer one.
85	 */
86	function isCurrent(held, next) {
87	  if (!held) return true;
88	  if (held.epoch !== next.epoch) return true;
89	  return next.revision >= held.revision;
90	}
91	
92	/**
93	 * The projects with their sessions, a project with a waiting session
94	 * first and waiting sessions first within each, the host's order kept
95	 * otherwise. Projects with no session are left out.
96	 */
97	function orderSessions(projects, sessionsByProject) {
98	  const waitingFirst = (list) => list
99	    .map((item, i) => ({ item, i }))
100	    .sort((a, b) => (b.item.waiting - a.item.waiting) || (a.i - b.i))
101	    .map((x) => x.item);
102	  const groups = projects
103	    .map((project) => ({
104	      project,
105	      sessions: waitingFirst((sessionsByProject[project.id] || []).map((s) => ({ ...s, waiting: !!s.waiting }))),
106	    }))
107	    .filter((g) => g.sessions.length > 0)
108	    .map((g) => ({ ...g, waiting: g.sessions.some((s) => s.waiting) }));
109	  return waitingFirst(groups).map(({ project, sessions }) => ({ project, sessions }));
110	}
111	
112	/** "just now", "5 min ago", "3 h ago", "2 d ago". */
113	function sinceText(ms, now) {
114	  if (ms == null) return '';
115	  const secs = Math.max(0, Math.floor((now - ms) / 1000));
116	  if (secs < 60) return 'just now';
117	  if (secs < 3600) return `${Math.floor(secs / 60)} min ago`;
118	  if (secs < 86400) return `${Math.floor(secs / 3600)} h ago`;
119	  return `${Math.floor(secs / 86400)} d ago`;
120	}
121	
122	/** A route from the table with its `{id}` filled. */
123	function route(entry, id) {
124	  const [method, path] = entry.split(' ');
125	  return { method, path: path.replace('{id}', encodeURIComponent(id || '')) };
126	}
127	
128	if (typeof module !== 'undefined' && module.exports) {
129	  module.exports = { API, parseFragment, deviceName, inferUnauthorized, isCurrent, orderSessions, sinceText, route };
130	}
131	
132	// --- the page
133	
134	if (typeof document !== 'undefined') {
135	  const $ = (id) => document.getElementById(id);
136	  const state = {
137	    me: null,
138	    listMark: null,
139	    open: null,
140	    held: {},
141	    pending: null,
142	    socket: null,
143	    socketRetry: SOCKET_RETRY_MS,
144	    pollMs: POLL_FAST_MS,
145	    timer: null,
146	  };
147	
148	  class HttpError extends Error {
149	    constructor(status, code, message) {
150	      super(message || code);
151	      this.status = status;
152	      this.code = code;
153	    }
154	  }
155	
156	  async function call(entry, id, body) {
157	    const { method, path } = route(entry, id);
158	    const init = { method, credentials: 'same-origin', cache: 'no-store', headers: {} };
159	    if (body !== undefined) {
160	      init.headers['Content-Type'] = 'application/json';
161	      init.body = JSON.stringify(body);
162	    }
163	    const response = await fetch(path, init);
164	    let json = null;
165	    try { json = await response.json(); } catch (_) { json = null; }
166	    if (!response.ok) {
167	      const error = (json && json.error) || {};
168	      throw new HttpError(response.status, error.code || 'failed', error.message);
169	    }
170	    return json;
171	  }
172	
173	  function stored() {
174	    try { return JSON.parse(localStorage.getItem(STORE_KEY)); } catch (_) { return null; }
175	  }
176	
177	  function show(section) {
178	    for (const id of ['notice', 'list', 'session']) $(id).hidden = id !== section;
179	    $('header').hidden = section === 'notice' || !state.me;
180	  }
181	
182	  function notice(title, text) {
183	    $('notice-title').textContent = title;
184	    $('notice-text').textContent = text;
185	    show('notice');
186	  }
187	
188	  const NOTICES = {
189	    unpaired: ['Not paired', 'Open Remote devices on the Mac, allow pairing, and scan its code with this phone.'],
190	    removed: ['This device was removed on the host', 'Pair again from the Mac’s Remote devices window.'],
191	    changed: ['Identity changed', 'The host at this address is not the one this browser paired with. Pair again.'],
192	    unreachable: ['Can’t reach the host', 'Check that the Mac is awake, Switchboard is running, and it allows devices on the local network.'],
193	  };
194	
195	  const PAIR_ERRORS = {
196	    pairing_closed: 'Pairing is not open on the Mac. Open it again and scan the new code.',
197	    wrong_code: 'The code did not match. Scan the code the Mac shows now.',
198	    wrong_key: 'The host refused the key. Scan the code again on the Mac you mean.',
199	    rate_limited: 'Too many attempts. Wait a minute and scan again.',
200	  };
201	
202	  async function unauthorized() {
203	    stopUpdates();
204	    const saved = stored();
205	    let info = null;
206	    if (saved) {
207	      try { info = (await call(API.info)).body; } catch (_) { info = null; }
208	    }
209	    const [title, text] = NOTICES[inferUnauthorized(saved, info)];
210	    state.me = null;
211	    notice(title, text);
212	  }
213	
214	  async function failed(error) {
215	    if (error instanceof HttpError && error.status === 401) return unauthorized();
216	    if (!(error instanceof HttpError)) return notice(...NOTICES.unreachable);
217	    return null;
218	  }
219	
220	  async function pair(invite) {
221	    let info;
222	    try { info = (await call(API.info)).body; } catch (_) { return notice(...NOTICES.unreachable); }
223	    if (String(info.spki_sha256).toLowerCase() !== invite.key || String(info.server_id).toLowerCase() !== invite.id) {
224	      return notice('Wrong host', 'This address is a different Switchboard than the code was for. Nothing was sent.');
225	    }
226	    try {
227	      await call(API.pair, null, {
228	        code: invite.code,
229	        spki_sha256: invite.key,
230	        device_name: deviceName(navigator.userAgent, navigator.maxTouchPoints || 0),
231	        transport: 'cookie',
232	      });
233	    } catch (error) {
234	      if (error instanceof HttpError) return notice('Pairing failed', PAIR_ERRORS[error.code] || error.message);
235	      return notice(...NOTICES.unreachable);
236	    }
237	    localStorage.setItem(STORE_KEY, JSON.stringify({
238	      server_id: invite.id,
239	      spki_sha256: invite.key,
240	      server_name: info.server_name,
241	    }));
242	    return start();
243	  }
244	
245	  async function start() {
246	    try {
247	      state.me = (await call(API.me)).body;
248	    } catch (error) {
249	      return failed(error);
250	    }
251	    $('host-name').textContent = state.me.server_name || 'Switchboard';
252	    $('scope').textContent = state.me.scope;
253	    await refreshList();
254	    startUpdates();
255	    return null;
256	  }
257	
258	  async function refreshList() {
259	    let projects;
260	    const sessionsByProject = {};
261	    let mark;
262	    try {
263	      const reply = await call(API.projects);
264	      mark = { epoch: reply.epoch, revision: reply.revision };
265	      projects = reply.body.projects || [];
266	      // One at a time, on the one kept connection: requests in
267	      // parallel would open new connections, and the host holds four
268	      // that have not yet authenticated before it refuses a fifth.
269	      for (const p of projects) {
270	        const r = await call(API.sessions, p.id);
271	        sessionsByProject[p.id] = r.body.sessions || [];
272	      }
273	    } catch (error) {
274	      return failed(error);
275	    }
276	    if (!isCurrent(state.listMark, mark)) return null;
277	    state.listMark = mark;
278	    state.sessions = {};
279	    for (const list of Object.values(sessionsByProject)) {
280	      for (const s of list) state.sessions[s.id] = s;
281	    }
282	    drawList(orderSessions(projects, sessionsByProject));
283	    if (state.open) {
284	      if (state.sessions[state.open]) await refreshSession();
285	      else closeSession();
286	    }
287	    return null;
288	  }
289	
290	  function drawList(groups) {
291	    const root = $('projects');
292	    root.replaceChildren();
293	    $('list-empty').hidden = groups.length > 0;
294	    const now = Date.now();
295	    for (const { project, sessions } of groups) {
296	      const heading = document.createElement('h3');
297	      heading.textContent = project.name;
298	      root.append(heading);
299	      for (const s of sessions) {
300	        const row = document.createElement('button');
301	        row.type = 'button';
302	        row.className = s.waiting ? 'row is-waiting' : 'row';
303	        if (s.waiting) {
304	          const w = document.createElement('p');
305	          w.className = 'waiting';
306	          w.textContent = s.waiting_reason ? `Waiting on you: ${s.waiting_reason}` : 'Waiting on you';
307	          row.append(w);
308	        }
309	        const name = document.createElement('div');
310	        name.className = 'name';
311	        name.textContent = s.name;
312	        const meta = document.createElement('div');
313	        meta.className = 'meta';
314	        meta.textContent = [s.kind, s.card, sinceText(s.last_activity_ms, now)].filter(Boolean).join(' · ');
315	        row.append(name, meta);
316	        row.addEventListener('click', () => openSession(s.id));
317	        root.append(row);
318	      }
319	    }
320	    if (!state.open) show('list');
321	  }
322	
323	  function openSession(id) {
324	    if (state.open !== id) {
325	      $('reply-text').value = '';
326	      $('reply-status').textContent = '';
327	      $('session-text').textContent = '';
328	      state.pending = null;
329	    }
330	    state.open = id;
331	    show('session');
332	    refreshSession();
333	  }
334	
335	  function closeSession() {
336	    state.open = null;
337	    show('list');
338	  }
339	
340	  async function refreshSession() {
341	    const id = state.open;
342	    const s = state.sessions && state.sessions[id];
343	    if (!s) return null;
344	    $('session-name').textContent = s.name;
345	    $('session-meta').textContent = [s.kind, s.card, sinceText(s.last_activity_ms, Date.now())].filter(Boolean).join(' · ');
346	    $('session-waiting').hidden = !s.waiting;
347	    $('session-waiting').textContent = s.waiting_reason ? `Waiting on you: ${s.waiting_reason}` : 'Waiting on you';
348	    const canReply = state.me && state.me.scope === 'control';
349	    $('reply').hidden = !canReply || s.prompt_refusal != null;
350	    $('session-refusal').hidden = !canReply || s.prompt_refusal == null;
351	    $('session-refusal').textContent = s.prompt_refusal ? `No reply from here: ${s.prompt_refusal}` : '';
352	    const entry = s.kind === 'claude' ? API.lastResponse : API.screen;
353	    const key = `${entry} ${id}`;
354	    try {
355	      const reply = await call(entry, id);
356	      if (state.open !== id || !isCurrent(state.held[key], reply)) return null;
357	      state.held[key] = { epoch: reply.epoch, revision: reply.revision };
358	      $('session-text').textContent = reply.body.text || '';
359	    } catch (error) {
360	      if (error instanceof HttpError && error.status !== 401) {
361	        if (state.open === id) $('session-text').textContent = error.message;
362	        return null;
363	      }
364	      return failed(error);
365	    }
366	    return null;
367	  }
368	
369	  function newOp() {
370	    const bytes = new Uint8Array(16);
371	    crypto.getRandomValues(bytes);
372	    return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
373	  }
374	
375	  async function send() {
376	    const id = state.open;
377	    const text = $('reply-text').value.trim();
378	    if (!id || !text) return null;
379	    // The same text to the same session keeps its op, so a retry after
380	    // a lost reply is answered from the host's log, not typed twice.
381	    if (!state.pending || state.pending.session !== id || state.pending.text !== text) {
382	      state.pending = { session: id, text, op: newOp() };
383	    }
384	    $('send').disabled = true;
385	    $('reply-status').textContent = 'Sending…';
386	    try {
387	      await call(API.send, id, { op: state.pending.op, text });
388	      state.pending = null;
389	      $('reply-text').value = '';
390	      $('reply-status').textContent = 'Sent.';
391	    } catch (error) {
392	      if (error instanceof HttpError && error.status === 403 && error.code === 'scope') {
393	        $('reply-status').textContent = 'This device reads only.';
394	        try { state.me = (await call(API.me)).body; $('scope').textContent = state.me.scope; } catch (_) { /* the next poll says */ }
395	        await refreshSession();
396	      } else if (error instanceof HttpError && error.status === 401) {
397	        await unauthorized();
398	      } else if (error instanceof HttpError) {
399	        $('reply-status').textContent = error.message;
400	      } else {
401	        $('reply-status').textContent = 'Not sure it went. Send again: it will not be typed twice.';
402	      }
403	    } finally {
404	      $('send').disabled = false;
405	    }
406	    return null;
407	  }
408	
409	  // --- updates: a poll, hastened by the events socket when it connects
410	
411	  async function poll() {
412	    state.timer = null;
413	    if (document.visibilityState === 'visible' && state.me) {
414	      try {
415	        const reply = await call(API.waiting);
416	        const mark = state.listMark;
417	        if (!mark || mark.epoch !== reply.epoch || mark.revision !== reply.revision) {
418	          await refreshList();
419	        }
420	      } catch (error) {
421	        await failed(error);
422	      }
423	    }
424	    if (state.me) schedule();
425	  }
426	
427	  function schedule() {
428	    if (state.timer) clearTimeout(state.timer);
429	    state.timer = setTimeout(poll, state.pollMs);
430	  }
431	
432	  function startUpdates() {
433	    state.pollMs = POLL_FAST_MS;
434	    schedule();
435	    openSocket();
436	  }
437	
438	  function stopUpdates() {
439	    if (state.timer) clearTimeout(state.timer);
440	    state.timer = null;
441	    if (state.socket) {
442	      state.socket.onclose = null;
443	      state.socket.close();
444	      state.socket = null;
445	    }
446	  }
447	
448	  function openSocket() {
449	    if (!state.me || state.socket) return;
450	    let socket;
451	    try {
452	      socket = new WebSocket(`wss://${location.host}${route(API.events).path}`);
453	    } catch (_) {
454	      return;
455	    }
456	    state.socket = socket;
457	    socket.onopen = () => {
458	      state.socketRetry = SOCKET_RETRY_MS;
459	      state.pollMs = POLL_SLOW_MS;
460	      schedule();
461	    };
462	    socket.onmessage = (event) => {
463	      let frame;
464	      try { frame = JSON.parse(event.data); } catch (_) { return; }
465	      if (frame.type === 'changed' || frame.type === 'removed' || frame.type === 'resync_required') {
466	        refreshList();
467	      }
468	    };
469	    socket.onclose = () => {
470	      state.socket = null;
471	      state.pollMs = POLL_FAST_MS;
472	      refreshList();
473	      schedule();
474	      const wait = state.socketRetry;
475	      state.socketRetry = Math.min(state.socketRetry * 2, SOCKET_RETRY_MAX_MS);
476	      setTimeout(openSocket, wait);
477	    };
478	  }
479	
480	  document.addEventListener('visibilitychange', () => {
481	    if (document.visibilityState === 'visible' && state.me) poll();
482	  });
483	
484	  document.addEventListener('DOMContentLoaded', () => {
485	    $('back').addEventListener('click', closeSession);
486	    $('send').addEventListener('click', send);
487	    const invite = parseFragment(location.hash);
488	    // The code leaves the address bar before anything else happens.
489	    if (location.hash) history.replaceState(null, '', location.pathname);
490	    if (invite) pair(invite);
491	    else start();
492	  });
493	}
494

