258	  async function refreshList() {
259	    let projects;
260	    const sessionsByProject = {};
261	    let mark;
262	    try {
263	      const reply = await call(API.projects);
264	      mark = { epoch: reply.epoch, revision: reply.revision };
265	      projects = reply.body.projects || [];
266	      // One at a time, on the one kept connection: requests in
267	      // parallel would open new connections, and the host holds four
268	      // that have not yet authenticated before it refuses a fifth.
269	      for (const p of projects) {
