272	      }
273	    } catch (error) {
274	      return failed(error);
275	    }
276	    if (!isCurrent(state.listMark, mark)) return null;
277	    state.listMark = mark;
278	    state.sessions = {};
279	    for (const list of Object.values(sessionsByProject)) {
280	      for (const s of list) state.sessions[s.id] = s;
281	    }
282	    drawList(orderSessions(projects, sessionsByProject));
283	    if (state.open) {
284	      if (state.sessions[state.open]) await refreshSession();
