290	  function drawList(groups) {
291	    const root = $('projects');
292	    root.replaceChildren();
293	    $('list-empty').hidden = groups.length > 0;
294	    const now = Date.now();
295	    for (const { project, sessions } of groups) {
296	      const heading = document.createElement('h3');
297	      heading.textContent = project.name;
298	      root.append(heading);
