340	  async function refreshSession() {
341	    const id = state.open;
342	    const s = state.sessions && state.sessions[id];
343	    if (!s) return null;
344	    $('session-name').textContent = s.name;
345	    $('session-meta').textContent = [s.kind, s.card, sinceText(s.last_activity_ms, Date.now())].filter(Boolean).join(' · ');
346	    $('session-waiting').hidden = !s.waiting;
347	    $('session-waiting').textContent = s.waiting_reason ? `Waiting on you: ${s.waiting_reason}` : 'Waiting on you';
348	    const canReply = state.me && state.me.scope === 'control';
349	    $('reply').hidden = !canReply || s.prompt_refusal != null;
350	    $('session-refusal').hidden = !canReply || s.prompt_refusal == null;
351	    $('session-refusal').textContent = s.prompt_refusal ? `No reply from here: ${s.prompt_refusal}` : '';
352	    const entry = s.kind === 'claude' ? API.lastResponse : API.screen;
353	    const key = `${entry} ${id}`;
354	    try {
355	      const reply = await call(entry, id);
356	      if (state.open !== id || !isCurrent(state.held[key], reply)) return null;
357	      state.held[key] = { epoch: reply.epoch, revision: reply.revision };
358	      $('session-text').textContent = reply.body.text || '';
359	    } catch (error) {
360	      if (error instanceof HttpError && error.status !== 401) {
361	        if (state.open === id) $('session-text').textContent = error.message;
362	        return null;
363	      }
364	      return failed(error);
365	    }
366	    return null;
367	  }
368	
369	  function newOp() {
370	    const bytes = new Uint8Array(16);
371	    crypto.getRandomValues(bytes);
372	    return Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');
373	  }
374	
375	  async function send() {
376	    const id = state.open;
377	    const text = $('reply-text').value.trim();
378	    if (!id || !text) return null;
379	    // The same text to the same session keeps its op, so a retry after
380	    // a lost reply is answered from the host's log, not typed twice.
381	    if (!state.pending || state.pending.session !== id || state.pending.text !== text) {
382	      state.pending = { session: id, text, op: newOp() };
383	    }
384	    $('send').disabled = true;
385	    $('reply-status').textContent = 'Sending…';
386	    try {
387	      await call(API.send, id, { op: state.pending.op, text });
388	      state.pending = null;
389	      $('reply-text').value = '';
390	      $('reply-status').textContent = 'Sent.';
391	    } catch (error) {
392	      if (error instanceof HttpError && error.status === 403 && error.code === 'scope') {
393	        $('reply-status').textContent = 'This device reads only.';
394	        try { state.me = (await call(API.me)).body; $('scope').textContent = state.me.scope; } catch (_) { /* the next poll says */ }
395	        await refreshSession();
396	      } else if (error instanceof HttpError && error.status === 401) {
397	        await unauthorized();
398	      } else if (error instanceof HttpError) {
399	        $('reply-status').textContent = error.message;
400	      } else {
401	        $('reply-status').textContent = 'Not sure it went. Send again: it will not be typed twice.';
402	      }
403	    } finally {
404	      $('send').disabled = false;
405	    }
406	    return null;
407	  }
408	
409	  // --- updates: a poll, hastened by the events socket when it connects
410	
411	  async function poll() {
412	    state.timer = null;
413	    if (document.visibilityState === 'visible' && state.me) {
414	      try {
415	        const reply = await call(API.waiting);
416	        const mark = state.listMark;
417	        if (!mark || mark.epoch !== reply.epoch || mark.revision !== reply.revision) {
418	          await refreshList();
419	        }
420	      } catch (error) {
421	        await failed(error);
422	      }
423	    }
424	    if (state.me) schedule();
425	  }
426	
427	  function schedule() {
428	    if (state.timer) clearTimeout(state.timer);
429	    state.timer = setTimeout(poll, state.pollMs);
430	  }
431	
432	  function startUpdates() {
433	    state.pollMs = POLL_FAST_MS;
434	    schedule();
435	    openSocket();
436	  }
437	
438	  function stopUpdates() {
439	    if (state.timer) clearTimeout(state.timer);
440	    state.timer = null;
441	    if (state.socket) {
442	      state.socket.onclose = null;
443	      state.socket.close();
444	      state.socket = null;
445	    }
446	  }
447	
448	  function openSocket() {
449	    if (!state.me || state.socket) return;
450	    let socket;
451	    try {
452	      socket = new WebSocket(`wss://${location.host}${route(API.events).path}`);
453	    } catch (_) {
454	      return;
455	    }
456	    state.socket = socket;
457	    socket.onopen = () => {
458	      state.socketRetry = SOCKET_RETRY_MS;
459	      state.pollMs = POLL_SLOW_MS;
460	      schedule();
461	    };
462	    socket.onmessage = (event) => {
463	      let frame;
464	      try { frame = JSON.parse(event.data); } catch (_) { return; }
465	      if (frame.type === 'changed' || frame.type === 'removed' || frame.type === 'resync_required') {
466	        refreshList();
467	      }
468	    };
469	    socket.onclose = () => {
470	      state.socket = null;
471	      state.pollMs = POLL_FAST_MS;
472	      refreshList();
473	      schedule();
474	      const wait = state.socketRetry;
475	      state.socketRetry = Math.min(state.socketRetry * 2, SOCKET_RETRY_MAX_MS);
476	      setTimeout(openSocket, wait);
477	    };
478	  }
479	
480	  document.addEventListener('visibilitychange', () => {
481	    if (document.visibilityState === 'visible' && state.me) poll();
482	  });
483	
484	  document.addEventListener('DOMContentLoaded', () => {
485	    $('back').addEventListener('click', closeSession);
486	    $('send').addEventListener('click', send);
487	    const invite = parseFragment(location.hash);
488	    // The code leaves the address bar before anything else happens.
489	    if (location.hash) history.replaceState(null, '', location.pathname);
490	    if (invite) pair(invite);
491	    else start();
492	  });
493	}
