pub fn invite_url(
    identity: &Identity,
    window: &PairingWindow,
    local: Option<IpAddr>,
    port: u16,
) -> String {
    let address = invite_address(identity, local, port)
        .unwrap_or_else(|| SocketAddr::new(IpAddr::V4(Ipv4Addr::LOCALHOST), port));
    format!(
        "https://{}/#code={}&key={}&id={}",
        address,
        window.code,
        identity.spki_sha256,
        identity.server_id
    )
}

